<?php require_once __DIR__.'/includes/functions.php';require_login();$uid=(int)user()['id'];if(isset($_GET['toggle'])){$id=(int)$_GET['toggle'];$c=car_by_id($pdo,$id);if($c){$s=$pdo->prepare('SELECT id FROM favourites WHERE user_id=? AND car_id=?');$s->execute([$uid,$id]);if($s->fetch()){$pdo->prepare('DELETE FROM favourites WHERE user_id=? AND car_id=?')->execute([$uid,$id]);flash('success','Car removed from saved list.');}else{$pdo->prepare('INSERT IGNORE INTO favourites(user_id,car_id) VALUES(?,?)')->execute([$uid,$id]);flash('success','Car saved to your list.');}}go('favourites.php');}$s=$pdo->prepare('SELECT c.* FROM cars c JOIN favourites f ON f.car_id=c.id WHERE f.user_id=? ORDER BY f.created_at DESC');$s->execute([$uid]);$cars=$s->fetchAll();$pageTitle='Saved cars';require __DIR__.'/includes/header.php'; ?>
<div class="page-intro"><span class="eyebrow">YOUR SHORTLIST</span><h1>Saved cars</h1><p class="muted">Keep the cars you are considering in one place.</p></div><div class="car-grid"><?php foreach($cars as $c): ?><article class="car-card"><a class="car-photo" href="<?= url('car.php?id='.$c['id']) ?>"><img src="<?= e(car_image($c['image_url'])) ?>" alt=""></a><div class="car-info"><h3><?= e($c['name']) ?></h3><div class="price"><?= money($c['price_min']) ?></div><a class="link" href="<?= url('favourites.php?toggle='.$c['id']) ?>">Remove from saved ×</a></div></article><?php endforeach; ?></div><?php if(!$cars): ?><div class="empty-state">No saved cars yet. Browse the catalogue and save your favourites.</div><?php endif; ?>
<?php require __DIR__.'/includes/footer.php'; ?>
